// scripts/lib/regiojet.mjs
// RegioJet night trains: the pure half of scripts/adapters/regiojet-gtfs.mjs.
//
// RegioJet publishes its own timetable as two GTFS files on its booking
// system's host (ybus.sa.cz), both regenerated by the operator:
//
//   - "Interstate"   /gtfe/google_transit.zip              — the domestic
//     Czech lines (R8 Brno–Bohumín, R23 Kolín–Ústí, the buses);
//   - "International" /gtfe/international/google_transit.zip — every train
//     and coach crossing a border, the night trains among them.
//
// Both are read, because which file carries a train is the operator's
// bookkeeping rather than a promise: on 23 October 2026 the night trains were
// all in the international file (RJ 1020/1021 Praha–Košice with through cars
// to Čop, RJ 1022/1023 Praha–Przemyśl) and the domestic one's latest train
// reached Bohumín at 23:34, but a domestic sleeper would land in the other.
//
// What counts as a night train is the clock, as for KTMB: a rail trip
// (route_type 2, or 100–117) that leaves at or after `minDepartureHour` and
// runs past midnight for at least `minMinutes`. No allowlist of numbers, so a
// new night train — RegioJet's summer services to the Adriatic are published
// in spring — is picked up the night it appears.
//
// What the feed says and how it is read:
//   - train number: `trip_short_name` ("RJ 1021"); the trains file is keyed by
//     the bare number ("1021") because Back-on-Track's labels are bare, and
//     shown as `lineName` ("RJ 1021").
//   - one number, several trips: RJ 1020 is filed twice, once from Čop (the
//     through cars, 18 stops) and once from Košice (the main train, 17 stops),
//     with their own service periods. A train is its modal stop pattern
//     weighted by dates, the fullest of a near tie (`pickRepresentativeRun`,
//     shared with Trafiklab) — so the Čop run, which is the Košice run plus
//     the leg to Čop.
//   - days: calendar.txt plus calendar_dates.txt, in the timetable period
//     running now (`pickServiceWindow`), rendered the way the row schema reads
//     (`renderServiceDays`): "2026: Daily" for a train running to the feed's
//     horizon, a dated season for one that stops short of it.
//   - pickup/drop-off: RegioJet does not sell a domestic journey on its
//     international sleepers — RJ 1023 takes passengers on in Czechia and only
//     sets them down in Poland. `pickup_type`/`drop_off_type` 1 is kept on
//     each station as `pickup: false` / `dropoff: false`.
//   - shapes: the feed's shapes.txt is one point per stop, i.e. the station
//     chain. A shape is used only when it is real track (`isRealShape`);
//     otherwise each gap between two stops borrows the track of a line that
//     runs between them (`trackPathFromSiblings`, params.siblingTracks). The
//     line is drawn only on a row this source creates; Back-on-Track's
//     RegioJet rows keep their hand-traced corridors.
//   - times: in the agency's zone, Europe/Prague; no stop carries a
//     stop_timezone. Čop is the one stop outside Central European time, and
//     its clocks are kept as the feed writes them (Back-on-Track has the same
//     17:35 and 10:38 there).
//
// Dependency-free bar the polyline encoder, so tests/verify-regiojet.mjs can
// run it against the feed's own tables.

import polyline from "@mapbox/polyline";
import { simplifyPath } from "./rail-graph.mjs";
import { haversineKm, trackPathFromSiblings } from "./sibling-path.mjs";
import {
  compactDate,
  pickRepresentativeRun,
  pickServiceWindow,
  renderServiceDays,
  serviceDatesById,
  upcomingDeviations,
} from "../adapters/trafiklab-gtfs.mjs";

/** "10:05:00" / "29:46:00" → minutes after the first day's midnight. */
export function gtfsMinutes(t) {
  const m = /^\s*(\d{1,3}):(\d{2})/.exec(String(t ?? ""));
  return m ? Number(m[1]) * 60 + Number(m[2]) : null;
}

/** Minutes after the first midnight → { time: "HH:MM", day }. */
export function clockOf(minutes) {
  if (!Number.isFinite(minutes)) return { time: null, day: null };
  const day = Math.floor(minutes / 1440);
  const m = minutes - day * 1440;
  return { time: `${String(Math.floor(m / 60)).padStart(2, "0")}:${String(m % 60).padStart(2, "0")}`, day };
}

/**
 * "RJ 1021" → "1021", "RJ 1005/1028" → "1005". The first run of three to six
 * digits: RegioJet writes the number after its brand, and a train renumbered
 * at a border carries both.
 */
export function trainNumberOf(tripShortName) {
  const m = String(tripShortName ?? "").match(/\d{3,6}/);
  return m ? m[0] : null;
}

/** GTFS route_type for a train: 2, or the extended 100–117 rail range. */
export function isRailRouteType(type) {
  const n = Number(type);
  return n === 2 || (n >= 100 && n <= 117);
}

/**
 * Both feeds as one: every id is prefixed with its feed's id, because the two
 * files are generated separately and nothing promises their ids are disjoint.
 *
 * @param {Array<{ id: string, tables: { routes, trips, stops, stopTimes, calendar, calendarDates, shapes } }>} feeds
 */
export function mergeFeeds(feeds) {
  const out = {
    routes: new Map(),
    trips: [],
    stopsById: new Map(),
    stopTimesByTrip: new Map(),
    calendar: [],
    calendarDates: [],
    shapes: new Map(),
    feedIds: [],
  };
  for (const { id, tables } of feeds) {
    if (!tables) continue;
    out.feedIds.push(id);
    const p = (v) => (v == null || v === "" ? "" : `${id}:${v}`);
    for (const r of tables.routes ?? []) out.routes.set(p(r.route_id), { ...r, route_id: p(r.route_id), feed: id });
    for (const t of tables.trips ?? []) {
      out.trips.push({ ...t, route_id: p(t.route_id), trip_id: p(t.trip_id), service_id: p(t.service_id), shape_id: p(t.shape_id), feed: id });
    }
    for (const s of tables.stops ?? []) out.stopsById.set(p(s.stop_id), { ...s, stop_id: p(s.stop_id), parent_station: p(s.parent_station) });
    for (const st of tables.stopTimes ?? []) {
      const key = p(st.trip_id);
      if (!out.stopTimesByTrip.has(key)) out.stopTimesByTrip.set(key, []);
      out.stopTimesByTrip.get(key).push({ ...st, trip_id: key, stop_id: p(st.stop_id) });
    }
    for (const c of tables.calendar ?? []) out.calendar.push({ ...c, service_id: p(c.service_id) });
    for (const c of tables.calendarDates ?? []) out.calendarDates.push({ ...c, service_id: p(c.service_id) });
    for (const pt of tables.shapes ?? []) {
      const key = p(pt.shape_id);
      if (!out.shapes.has(key)) out.shapes.set(key, []);
      out.shapes.get(key).push(pt);
    }
  }
  for (const [key, pts] of out.shapes) {
    out.shapes.set(
      key,
      pts
        .sort((a, b) => Number(a.shape_pt_sequence) - Number(b.shape_pt_sequence))
        .map((pt) => [Number(pt.shape_pt_lat), Number(pt.shape_pt_lon)])
        .filter(([a, b]) => Number.isFinite(a) && Number.isFinite(b)),
    );
  }
  return out;
}

// ─── Station names ──────────────────────────────────────────────────────────

/**
 * The feed's spelling, made comparable to the rest of the dataset's:
 * "Košice, žst." → "Košice", "Ostrava, hl.n." → "Ostrava hl.n.",
 * "Kysak (u města Prešov), žst." → "Kysak", "Poprad, Tatry" → "Poprad Tatry".
 * RegioJet writes "town, station" with Czech or Slovak station-type suffixes
 * (žst. = železniční stanice, žel. st. = železničná stanica, nádr. = nádraží).
 */
export function normalizeFeedStationName(name) {
  return String(name ?? "")
    .replace(/\s*\([^)]*\)/g, "")
    .replace(/,\s*(?:žst|žel\.\s*st|nádr|žel\.\s*stan)\.?\s*$/i, "")
    .replace(/,\s*hl\.\s*n\.\s*$/i, " hl.n.")
    .replace(/,\s+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

/** Spellings to try for a feed station, most specific first. */
export function nameCandidates(feedName) {
  const raw = String(feedName ?? "").trim();
  const norm = normalizeFeedStationName(raw);
  const out = [];
  const push = (v) => {
    const s = String(v ?? "").trim();
    if (s && !out.includes(s)) out.push(s);
  };
  push(norm);
  // "Ostrava, Svinov" is "Ostrava-Svinov" in the dataset: a district of the
  // town, joined with a hyphen.
  const comma = raw.replace(/\s*\([^)]*\)/g, "").match(/^([^,]+),\s*([^,]+)$/);
  if (comma && !/^(?:žst|žel|nádr|hl\.)/i.test(comma[2])) push(`${comma[1].trim()}-${comma[2].trim()}`);
  push(raw.split(",")[0].replace(/\s*\([^)]*\)/g, ""));
  push(raw);
  return out;
}

/**
 * Name a feed station the way the rest of the payload does, but only where
 * that name is provably the same place.
 *
 * A via station becomes a map dot only when a coordinate-bearing stop of that
 * exact name exists, so reusing the dataset's spelling is what buys the dot.
 * Each candidate (the feed's spelling normalised, then run through the alias
 * table — which already maps RegioJet's Czech exonyms, "Krakov, Hlavní
 * nádraží" → "Kraków Gł.") is accepted only when a stop of that name lies
 * within `matchKm` of the feed's own coordinate: a name is not a location.
 * A station with no such match keeps its normalised name, and the build
 * injects it at the feed's coordinate.
 *
 * @param {{ stops: Array<{stop_name: string, stop_lat, stop_lon}>, resolveAlias?: (n: string) => string, stationNames?: object, matchKm?: number }} args
 * @returns {(stop: { name: string, lat: number, lon: number }) => { name: string, matched: boolean }}
 */
export function makeStationNamer({ stops = [], resolveAlias = (n) => n, stationNames = {}, matchKm = 3 } = {}) {
  const byName = new Map();
  for (const s of stops) {
    const name = String(s?.stop_name ?? "").trim();
    const lat = Number(s?.stop_lat);
    const lon = Number(s?.stop_lon);
    if (!name || !Number.isFinite(lat) || !Number.isFinite(lon)) continue;
    if (!byName.has(name)) byName.set(name, []);
    byName.get(name).push([lat, lon]);
  }
  const pinned = new Map(
    Object.entries(stationNames ?? {})
      .filter(([k]) => !k.startsWith("_"))
      .map(([k, v]) => [k.trim(), v]),
  );
  const near = (name, point) => (byName.get(name) ?? []).some((c) => haversineKm(c, point) <= matchKm);
  return ({ name, lat, lon }) => {
    const point = [lat, lon];
    const fixed = pinned.get(String(name ?? "").trim());
    if (fixed) return { name: fixed, matched: near(fixed, point) };
    const tried = [];
    for (const cand of nameCandidates(name)) {
      for (const n of [resolveAlias(cand), resolveAlias(cand.toLowerCase()), cand]) {
        if (!n || tried.includes(n)) continue;
        tried.push(n);
        if (near(n, point)) return { name: n, matched: true };
      }
    }
    const fallback = normalizeFeedStationName(name);
    return { name: resolveAlias(fallback) || fallback, matched: false };
  };
}

// ─── Night runs ─────────────────────────────────────────────────────────────

/**
 * Every night run in the merged feed, grouped by train number.
 *
 * @returns {{ byNumber: Map<string, Array<object>>, skipped: string[] }}
 */
export function nightRuns(feed, config = {}, nameStop = ({ name }) => ({ name, matched: false })) {
  const minMinutes = config.minMinutes ?? 300;
  const minDep = (config.minDepartureHour ?? 17) * 60;
  const exclude = new Set((config.exclude ?? []).map(String));
  const datesById = serviceDatesById(feed.calendar, feed.calendarDates);
  const byNumber = new Map();
  const skipped = [];
  const names = new Map();
  for (const trip of feed.trips) {
    const route = feed.routes.get(trip.route_id);
    if (!route || !isRailRouteType(route.route_type)) continue;
    const number = trainNumberOf(trip.trip_short_name);
    if (!number || exclude.has(number)) continue;
    const st = [...(feed.stopTimesByTrip.get(trip.trip_id) ?? [])].sort((a, b) => Number(a.stop_sequence) - Number(b.stop_sequence));
    if (st.length < 2) continue;
    const dep = gtfsMinutes(st[0].departure_time || st[0].arrival_time);
    const arr = gtfsMinutes(st.at(-1).arrival_time || st.at(-1).departure_time);
    if (dep == null || arr == null) continue;
    const length = arr >= dep ? arr - dep : arr + 1440 - dep;
    const crosses = arr >= 1440 || arr < dep;
    if (!(crosses && length >= minMinutes && dep >= minDep)) continue;

    const stops = [];
    for (const s of st) {
      const own = feed.stopsById.get(s.stop_id) ?? {};
      const parent = own.parent_station ? feed.stopsById.get(own.parent_station) : null;
      const station = parent ?? own;
      const lat = Number(station.stop_lat ?? own.stop_lat);
      const lon = Number(station.stop_lon ?? own.stop_lon);
      let a = gtfsMinutes(s.arrival_time);
      let d = gtfsMinutes(s.departure_time);
      // A feed writing "next day" as an earlier clock rather than 24+.
      const last = stops.length ? stops.at(-1).depMin ?? stops.at(-1).arrMin : dep;
      while (a != null && a < last) a += 1440;
      while (d != null && a != null && d < a) d += 1440;
      const feedName = station.stop_name ?? own.stop_name ?? s.stop_id;
      const key = station.stop_id ?? s.stop_id;
      if (!names.has(key)) names.set(key, nameStop({ name: feedName, lat, lon }));
      // RegioJet's booking system addresses the same places by the same ids:
      // a parent stop_id is its STATION id (Praha hl.n. 372825000) and the
      // zone_id its CITY id (Praha 10202003) — what the fare search and the
      // Book link need. The merge prefixed them with the feed; strip it.
      const raw = (v) => String(v ?? "").replace(/^[^:]*:/, "") || null;
      stops.push({
        station: key,
        stationId: raw(station.stop_id ?? s.stop_id),
        cityId: raw(station.zone_id ?? own.zone_id),
        feedName,
        name: names.get(key).name,
        matched: names.get(key).matched,
        lat,
        lon,
        arrMin: a,
        depMin: d,
        arrival: s.arrival_time || null,
        departure: s.departure_time || null,
        pickup: String(s.pickup_type ?? "") !== "1",
        dropoff: String(s.drop_off_type ?? "") !== "1",
      });
    }
    if (!byNumber.has(number)) byNumber.set(number, []);
    byNumber.get(number).push({
      tripId: trip.trip_id,
      feed: trip.feed,
      routeId: trip.route_id,
      routeName: route.route_long_name ?? "",
      serviceId: trip.service_id,
      shapeId: trip.shape_id,
      lineName: String(trip.trip_short_name ?? "").trim() || `RJ ${number}`,
      dates: datesById.get(trip.service_id) ?? new Set(),
      stops,
    });
  }
  for (const n of exclude) skipped.push(`${n} (excluded)`);
  return { byNumber, skipped };
}

/**
 * A feed shape is real track only when it carries clearly more points than
 * the trip has stops: RegioJet's shapes.txt is the station chain, one point a
 * stop, and drawing it would be a straight stroke from station to station.
 */
export function isRealShape(points, stopCount) {
  return Array.isArray(points) && points.length >= Math.max(3 * stopCount, 20);
}

/** Outbound/return pairs in file order: the lower number first, then its partner (n / n+1). */
export function pairOrder(numbers) {
  const set = new Set(numbers);
  const out = [];
  const seen = new Set();
  for (const n of [...numbers].sort((a, b) => Number(a) - Number(b) || a.localeCompare(b))) {
    if (seen.has(n)) continue;
    out.push(n);
    seen.add(n);
    const partner = Number(n) % 2 === 0 ? String(Number(n) + 1) : String(Number(n) - 1);
    if (set.has(partner) && !seen.has(partner)) {
      out.push(partner);
      seen.add(partner);
    }
  }
  return out;
}

/**
 * How long a train the feeds stopped carrying is kept from last night's file:
 * an outage of RegioJet's host for a few nights should not blank its trains,
 * and a month without one is no longer a timetable.
 */
export const CARRY_MAX_DAYS = 30;

/**
 * The line a train is drawn along: the feed's own shape when it is real track,
 * otherwise each gap between two stops taken, in order, from a sibling line
 * that runs between them (`donors`: the hand-traced RegioJet corridors, PKP's
 * GTFS track, ČD's and Nightjet's lines), straight only where none runs.
 * Every stop stays an exact vertex through the simplification, so a station
 * never falls off its line.
 */
export function trainLine(stops, { shape = null, donors = [], toleranceM = 20 } = {}) {
  const points = stops.map((s) => [s.lat, s.lon]);
  if (isRealShape(shape, stops.length)) {
    return { path: simplifyPath(shape, toleranceM), geometry: { feed: stops.length - 1 } };
  }
  const path = [points[0]];
  const keep = new Set([0]);
  const geometry = {};
  const count = (k) => {
    geometry[k] = (geometry[k] ?? 0) + 1;
  };
  for (let i = 0; i < points.length - 1; i++) {
    const a = points[i];
    const b = points[i + 1];
    const sib = trackPathFromSiblings([a, b], donors);
    let seg = null;
    if (sib.filled) {
      seg = sib.path;
      count("siblings");
    } else {
      seg = [a, b];
      count("chord");
    }
    path.push(...seg.slice(1, -1), b);
    keep.add(path.length - 1);
  }
  return { path: simplifyPath(path, toleranceM, keep), geometry };
}

/**
 * The trains file entries.
 *
 * @param {object} args
 * @param {object} args.config     data/sources/regiojet-sleepers.json
 * @param {object|null} args.feed  mergeFeeds' answer, or null when no feed could be read
 * @param {(stop) => {name, matched}} [args.nameStop]
 * @param {[number, number][][]} [args.donors]  sibling lines to borrow track from
 * @param {object} [args.previous] last night's trains, carried when the feed is down
 * @param {string} args.today      "YYYY-MM-DD"
 */
export function buildRegiojetTrains({ config = {}, feed, nameStop, donors = [], previous = {}, today, log = () => {} }) {
  const operator = config.operator ?? {};
  const prevByNumber = new Map(Object.values(previous ?? {}).map((t) => [String(t.trainNo ?? ""), t]));
  const fresh = (t) => {
    const at = Date.parse(`${t?.timetable?.checkedAt ?? ""}T00:00:00Z`);
    return Number.isFinite(at) && (Date.parse(`${today}T00:00:00Z`) - at) / 86_400_000 <= CARRY_MAX_DAYS;
  };

  if (!feed) {
    const trains = {};
    for (const n of pairOrder([...prevByNumber.keys()].filter((n) => n && fresh(prevByNumber.get(n))))) {
      const prev = prevByNumber.get(n);
      trains[n] = { ...prev, timetable: { ...prev.timetable, source: "previous" } };
    }
    return trains;
  }

  const { byNumber } = nightRuns(feed, config, nameStop);
  const todayC = compactDate(today);
  // The feed's horizon: the last date any of its services runs. A train
  // stopping well short of it is seasonal; one reaching it runs on.
  let horizonEnd = null;
  for (const runs of byNumber.values()) {
    for (const r of runs) for (const d of r.dates) if (!horizonEnd || d > horizonEnd) horizonEnd = d;
  }

  const trains = {};
  for (const number of pairOrder([...byNumber.keys()])) {
    const all = byNumber.get(number);
    const future = new Set();
    for (const r of all) for (const d of r.dates) if (d >= todayC) future.add(d);
    if (!future.size) {
      log(`${number}: every run is in the past — left out`);
      continue;
    }
    const window = pickServiceWindow(todayC, future);
    let inWindow = (d) => d >= window.start && (!window.end || d < window.end);
    if (![...future].some(inWindow)) {
      // A train announced for a later period (a summer service published in
      // spring): describe the period it does run in.
      const first = [...future].sort()[0];
      inWindow = (d) => d >= first;
    }
    const runs = all.map((r) => ({ ...r, dates: new Set([...r.dates].filter(inWindow)) })).filter((r) => r.dates.size);
    const rep = pickRepresentativeRun(runs);
    if (!rep) continue;
    const missing = rep.stops.filter((s) => !Number.isFinite(s.lat) || !Number.isFinite(s.lon));
    if (missing.length) {
      log(`${number}: no position for ${missing.map((s) => s.feedName).join(", ")} — left out`);
      continue;
    }
    const dates = new Set();
    for (const r of runs) {
      // Only runs that are this train between the same two ends lend it their
      // days: the Košice portion of RJ 1020 runs the same nights as the Čop
      // one today, but a portion with its own calendar must not widen the
      // through train's.
      if (r.stops[0].station === rep.stops[0].station && r.stops.at(-1).station === rep.stops.at(-1).station) {
        for (const d of r.dates) dates.add(d);
      }
    }
    const frequency = renderServiceDays(dates, { horizonStart: todayC, horizonEnd });

    const base = rep.stops[0].depMin;
    const dayBase = Math.floor(base / 1440) * 1440;
    const stations = rep.stops.map((s, i) => {
      const first = i === 0;
      const last = i === rep.stops.length - 1;
      const a = first ? { time: null, day: null } : clockOf(s.arrMin - dayBase);
      const d = last ? { time: null, day: null } : clockOf(s.depMin - dayBase);
      return {
        name: s.name,
        code: s.stationId,
        cityId: s.cityId,
        location: { latitude: s.lat, longitude: s.lon },
        arrival: a.time,
        departure: d.time,
        arrivalDay: a.day,
        departureDay: d.day,
        pickup: s.pickup,
        dropoff: s.dropoff,
      };
    });

    const { path, geometry } = trainLine(rep.stops, { shape: feed.shapes.get(rep.shapeId), donors });
    if (geometry.chord) log(`${number}: ${geometry.chord} of ${rep.stops.length - 1} gap(s) drawn straight — no sibling line runs between those stops`);
    const unmatched = rep.stops.filter((s) => !s.matched).map((s) => s.feedName);
    if (unmatched.length) log(`${number}: no dataset station within reach for ${unmatched.join(", ")} — kept under the feed's name`);

    const deviations = upcomingDeviations(all, rep, { today: todayC, days: 14, nameOf: (s) => s.name });
    const windowEnd = [...dates].sort().at(-1);
    trains[number] = {
      lineName: `${config.lineNamePrefix ?? "RJ"} ${number}`,
      trainNo: number,
      service: rep.routeName || null,
      operator: operator.name ?? "RegioJet",
      agency_id: operator.agencyId ?? "RJ",
      frequency: frequency ?? null,
      durationMinutes: rep.stops.at(-1).arrMin - base,
      nights: Math.floor(rep.stops.at(-1).arrMin / 1440) - Math.floor(base / 1440),
      polyline: polyline.encode(path),
      geometry,
      stations,
      ...(deviations.length ? { deviations } : {}),
      timetable: {
        source: "official",
        feed: rep.feed,
        checkedAt: today,
        ...(windowEnd ? { validUntil: `${windowEnd.slice(0, 4)}-${windowEnd.slice(4, 6)}-${windowEnd.slice(6, 8)}` } : {}),
      },
    };
  }
  // A feed that was read is authoritative: a train it no longer carries is
  // gone (the scrape runner's sticky merge still holds it for seven days).
  return trains;
}

/** Distance of a path, for logs. */
export function pathKm(path) {
  let km = 0;
  for (let i = 1; i < path.length; i++) km += haversineKm(path[i - 1], path[i]);
  return km;
}
